mod tests {
    use super::*;
    use chrono::{TimeZone, Utc};

    fn entry(duration: i64, start: &str, billable: bool, stop: Option<&str>) -> TimeEntry {
        let start = Utc.datetime_from_str(start, "%Y-%m-%dT%H:%M:%SZ").unwrap();
        let stop = stop.map(|value| Utc.datetime_from_str(value, "%Y-%m-%dT%H:%M:%SZ").unwrap());
        TimeEntry {
            start,
            stop,
            duration,
            billable,
            ..TimeEntry::default()
        }
    }

    #[test]
    fn applies_rounding_then_minimum_per_entry() {
        assert_eq!(invoiced_seconds(1), 1800);
        assert_eq!(invoiced_seconds(1800), 1800);
        assert_eq!(invoiced_seconds(1801), 2700);
        assert_eq!(invoiced_seconds(3600), 3600);
    }

    #[test]
    fn groups_only_closed_billable_entries_by_utc_start_month() {
        let entries = vec![
            entry(
                1,
                "2026-01-31T23:30:00Z",
                true,
                Some("2026-02-01T00:00:00Z"),
            ),
            entry(
                1800,
                "2026-02-01T00:00:00Z",
                true,
                Some("2026-02-01T00:30:00Z"),
            ),
            entry(
                3600,
                "2026-02-01T12:00:00Z",
                false,
                Some("2026-02-01T13:00:00Z"),
            ),
            entry(-1, "2026-02-02T12:00:00Z", true, None),
        ];

        assert_eq!(
            monthly_totals(&entries),
            BTreeMap::from([
                (String::from("2026-01"), 1800),
                (String::from("2026-02"), 1800)
            ])
        );
    }
}

